#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

pthread_mutex_t shared_mutex = PTHREAD_MUTEX_INITIALIZER;

// 1. The cleanup handler routine
void cleanup_routine(void *arg) {
    pthread_mutex_t *mutex = (pthread_mutex_t *)arg;
    int s = pthread_mutex_unlock(mutex);
    if (s == 0) {
        printf("[Cleanup Handler] Mutex unlocked successfully.\n");
    } else {
        fprintf(stderr, "[Cleanup Handler] Error unlocking mutex.\n");
    }
}

void *thread_func(void *arg) {
    printf("[Worker] Attempting to lock mutex.\n");
    pthread_mutex_lock(&shared_mutex);
    printf("[Worker] Mutex locked. Pushing cleanup handler.\n");

    // 2. Push the cleanup handler onto the stack
    pthread_cleanup_push(cleanup_routine, &shared_mutex);

    // Simulation of critical work (cancellation point)
    printf("[Worker] Working (sleeping for 5 seconds).\n");
    sleep(5);

    // If the thread reaches here, the work is done. We pop the handler 
    // and execute it immediately to release the resource cleanly.
    // execute=1 ensures the unlock happens.
    printf("[Worker] Work complete. Popping and executing handler.\n");
    pthread_cleanup_pop(1);

    return NULL;
}

int main() {
    pthread_t thread;

    if (pthread_create(&thread, NULL, thread_func, NULL) != 0) {
        perror("pthread_create");
        return 1;
    }

    // In a real scenario, we might cancel the thread after 1 second
    // to demonstrate the handler executing upon cancellation.
    // Here, we let it run to completion to demonstrate the explicit pop(1).

    // To test cancellation, uncomment the following:
    // sleep(1);
    // printf("[Main] Canceling worker thread.\n");
    // pthread_cancel(thread);

    pthread_join(thread, NULL);
    printf("[Main] Thread joined. Program exiting.\n");

    return 0;
}
